import numpy as np

def candidates(g, bg):
 a=np.array(g); H,W=a.shape; out=[]
 for c in set(a.flatten())-{bg}:
  ii=np.pad((a==c).astype(int),((1,0),(1,0))).cumsum(0).cumsum(1)
  def sm(r1,c1,r2,c2): return ii[r2+1,c2+1]-ii[r1,c2+1]-ii[r2+1,c1]+ii[r1,c1]
  cs=[]
  for r1 in range(H):
   for r2 in range(r1+1,H):
    for c1 in range(W):
     for c2 in range(c1+1,W):
      area=(r2-r1+1)*(c2-c1+1); n=sm(r1,c1,r2,c2)
      if n>=4 and n/area>=.60: cs.append((area,n,r1,c1,r2,c2,c))
  # only non-contained candidates
  cs.sort(reverse=True)
  keep=[]
  for x in cs:
   _,_,r1,c1,r2,c2,_=x
   if not any(y[2]<=r1 and y[3]<=c1 and y[4]>=r2 and y[5]>=c2 for y in keep): keep.append(x)
  out+=keep[:20]
 return sorted(out,reverse=True)
