from collections import Counter, deque

def transform(grid):
    h,w=len(grid),len(grid[0]); bg=Counter(x for row in grid for x in row).most_common(1)[0][0]
    seen=set(); objs=[]
    for r in range(h):
      for c in range(w):
       col=grid[r][c]
       if col==bg or (r,c) in seen: continue
       q=[(r,c)]; seen.add((r,c)); cells=[]
       while q:
        rr,cc=q.pop(); cells.append((rr,cc))
        for nr,nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
         if 0<=nr<h and 0<=nc<w and (nr,nc) not in seen and grid[nr][nc]==col:
          seen.add((nr,nc));q.append((nr,nc))
       if len(cells)>=4:
        objs.append((col,min(x[0] for x in cells),min(x[1] for x in cells),max(x[0] for x in cells),max(x[1] for x in cells)))
    out=[[bg]*w for _ in range(h)]
    for col,r1,c1,r2,c2 in objs:
      for r in range(r1,r2+1):
       for c in range(c1,c2+1): out[r][c]=col
    return out

